// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // Admin (this contract, the deployer) transfers ownership to an arbitrary address.
        vm.assume(newOwner != address(this)); // newOwner is not the admin
        c.setOwner(newOwner);

        // Rule: once ownership sits with a non-admin, that non-admin (or anyone else
        // who is not the admin) must NOT be able to change the owner — only the
        // admin can. The mutant lets the current owner succeed instead.
        address nextOwner;
        unchecked { nextOwner = address(uint160(newOwner) ^ 1); }
        if (nextOwner == address(this)) {
            nextOwner = address(uint160(newOwner) + 1);
        }

        vm.prank(newOwner); // caller is the (new) owner, but NOT the admin
        bool ok;
        try c.setOwner(nextOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && c.owner() == newOwner, "non-admin must never change owner");
    }
}
